class Solution:
    def demo(self, nums):
        seen = {}
        for i, x in enumerate(nums):
            if x in seen:  # viz:check
                return [seen[x], i]  # viz:found
            seen[x] = i  # viz:store
        return []

class Solution:
    def demo(self, nums, target):
        l, r = 0, len(nums) - 1
        while l < r:
            s = nums[l] + nums[r]  # viz:sum
            if s == target:
                return [l, r]  # viz:found
            if s < target:
                l += 1  # viz:move_l
            else:
                r -= 1  # viz:move_r
        return []

class Solution:
    def demo(self, nums):
        ans = [-1] * len(nums)
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] < x:
                ans[stack.pop()] = x  # viz:pop
            stack.append(i)  # viz:push
        return ans  # viz:done

class Solution:
    def demo(self, nums, k):
        l = 0
        total = 0
        best = 0
        for r in range(len(nums)):
            total += nums[r]  # viz:grow
            while total > k:
                total -= nums[l]  # viz:shrink
                l += 1
            best = max(best, r - l + 1)  # viz:record
        return best  # viz:done

class Solution:
    def demo(self, nums, target):
        lo, hi = 0, len(nums) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target:  # viz:check
                return mid  # viz:found
            if nums[mid] < target:
                lo = mid + 1  # viz:go_right
            else:
                hi = mid - 1  # viz:go_left
        return -1
